<?php
require_once "db.php"; require_login();
if(($_SESSION["role"]??"")!=="admin"){ http_response_code(403); exit("Access denied. Admin accounts only."); }
$users=$conn->query("SELECT id,name,phone,email,role,created_at FROM users ORDER BY id DESC");
$alerts=$conn->query("SELECT a.id,a.alert_type,a.location_text,a.status,a.alert_time,u.name,u.email FROM alerts a JOIN users u ON u.id=a.user_id ORDER BY a.alert_time DESC LIMIT 100");
?>
